INSERT OR REPLACE INTO _collections (collection_name, doc_id, data) VALUES ('settings', 'site', '{"hero":{"badge":"High-Retention Video Agency • Global Reach","headline1":"Creative videos.","headline2":"Built to move brands.","subheadline":"We combine strategic storytelling, high-end video editing, motion graphics, and creative production to help SaaS companies, founders, creators, and ambitious brands stand out.","cta1":"LET''S WORK TOGETHER","cta1Link":"/contact","cta2":"EXPLORE OUR WORK","cta2Link":"#work","socialProofText":"Founder Reviews","socialProofCount":"50+","showreelVideoId":"q7hCvbfvRPU"},"process":{"title":"From idea to impact.","subtitle":"OUR CREATIVE FRAMEWORK","description":"A clear creative process designed to take your vision from concept to final delivery.","steps":[{"id":"step-1","label":"01","title":"Discover","description":"Understand the audience, define the objective, and establish the creative direction.","icon":"Search","tags":["Audience Context","Core Objective","Creative Direction"],"previews":[]},{"id":"step-2","label":"02","title":"Create","description":"Develop the story, produce the visuals, and bring everything together through thoughtful creative execution.","icon":"Wand2","tags":["Visual Storytelling","2D/3D Motion","Creative Craft"],"previews":[]},{"id":"step-3","label":"03","title":"Deliver","description":"Refine, finalize, and deliver content ready to make an impact across your chosen platforms.","icon":"Rocket","tags":["Precision Polish","Multi-Platform Export","Launch Ready"],"previews":[]}]},"difference":{"title":"The Motionly approach.","subtitle":"HOW WE WORK","description":"Strategy, creativity, and execution come together to create videos that make a difference.","statusQuoTitle":"A fragmented workflow","statusQuoPoints":["Creative direction changes between contributors","Feedback and files are spread across tools","The edit starts before the story is clear","Publishing depends on one-off effort"],"motionlyTitle":"Motionly Media","motionlyPoints":["A clear owner from brief to delivery","Strategic storytelling and audience context","A consistent review and delivery process","Custom motion, sound, and visual finishing"]},"painPoints":{"title":"From the first idea to the final frame.","subtitle":"YOUR CREATIVE PARTNER","description":"Whether you''re building a personal brand, launching a product, or growing a business, we bring the creative direction and execution to make your vision happen.","points":["Creating consistent content takes more than just editing.","Your ideas need the right storytelling and visual direction.","Finding reliable creative talent shouldn''t slow down your growth.","Managing multiple creative requirements shouldn''t become another full-time job."]},"seo":{"title":"Motionly Media | Creative & Video Marketing Agency","description":"Motionly is a creative and video marketing agency helping SaaS companies, founders, creators, and ambitious brands turn ideas into impactful visual experiences.","image":"https://motionly.media/og-image-v2.png"},"contact":{"calendlyUrl":"https://cal.com/motionly-media-rdgfxc/30min","email":"support@motionly.media","phone":"","facebook":"https://www.facebook.com/motionlymedia","instagram":"https://www.instagram.com/motionlymedia/","linkedin":"https://www.linkedin.com/company/motionlymedia/"},"global":{"siteName":"Motionly Media","siteDescription":"Motionly is a creative and video marketing agency helping SaaS companies, founders, creators, and ambitious brands turn ideas into impactful visual experiences.","logoUrl":"/nav_logo.webp","faviconUrl":"/favicon.ico","maintenanceMode":false,"maintenanceMessage":"We are currently updating our systems to serve you better. The site remains fully functional.","pageToggles":{"personalBranding":true,"services":true,"portfolio":true,"about":true}},"layout":{"homepageSections":["hero","partners","portfolio","painPoints","difference","testimonials","process","team","pricing","blog","faqs","contact"]},"partners":{"layers":1},"updatedAt":{"seconds":1793355648}}');
