INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-1', '{"id":"faq-1","question":"What types of businesses and creators do you work with?","answer":"We partner with SaaS companies, technology startups, founders, content creators, personal brands, and growing businesses worldwide who want to create high-impact, story-driven video content.","order":1}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-2', '{"id":"faq-2","question":"What creative and video services do you offer?","answer":"Our core services include SaaS product videos, software explainers, 2D and 3D motion graphics, launch videos, personal branding content, commercial campaigns, and full-cycle creative video marketing.","order":2}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-3', '{"id":"faq-3","question":"Do you specialize in SaaS and technology videos?","answer":"Yes, technology and SaaS video production is our strongest core specialization. We translate complex software workflows and abstract technical concepts into intuitive, beautifully animated visual narratives.","order":3}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-4', '{"id":"faq-4","question":"Can you help founders and creators build personal brands?","answer":"Absolutely. We help founders and creators develop authoritative personal brands through high-retention video systems, talking-head editing, strategic hook architecture, and multi-platform content repurposing.","order":4}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-5', '{"id":"faq-5","question":"Do you offer filming and on-location production?","answer":"Yes. While most of our client engagements focus on digital post-production and motion design, we can provide professional filming, cinematography, studio shoots, and on-location production support whenever your project requires it.","order":5}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-6', '{"id":"faq-6","question":"Can we work with you on a monthly basis?","answer":"Yes. We offer both dedicated monthly creative partnerships for ongoing publishing needs and milestone-based engagements for standalone product launches and commercial projects.","order":6}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-7', '{"id":"faq-7","question":"How does your creative process work?","answer":"Our framework follows three simple stages: Discover (understanding your goals and audience), Create (story development, visual production, and motion design), and Deliver (refining details and packaging for launch).","order":7}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-8', '{"id":"faq-8","question":"Can you work with our existing brand identity?","answer":"Yes. During onboarding, we study your typography, brand guidelines, color palettes, and voice to ensure every video looks and feels authentically aligned with your brand.","order":8}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-9', '{"id":"faq-9","question":"Who owns the final video assets?","answer":"You own 100% of the commercial rights to all delivered videos and final renders upon completion. Source files and project assets can also be packaged upon request.","order":9}');
INSERT INTO _collections (collection_name, doc_id, data) VALUES ('faqs', 'faq-10', '{"id":"faq-10","question":"How do revisions and feedback work?","answer":"We conduct frame-accurate revision rounds via Frame.io. You can pause at any timestamp, leave direct visual feedback, and our team implements changes swiftly until the cut is finalized.","order":10}');
INSERT OR REPLACE INTO _collections (collection_name, doc_id, data) VALUES ('pricing', 'starter', '{"id":"starter","name":"Starter Sprint","price":"2,500","period":"month","description":"Establish your visual presence and produce high-impact core video assets.","features":["Up to 4 high-retention short-form videos / mo","1 core product or brand showcase video","Story direction & script assistance","2D kinetic typography & custom sound design","48-hour sprint turnaround","Dedicated Frame.io review workspace"],"recommended":false,"popular":false,"cta":"Get Started","order":1}');
INSERT OR REPLACE INTO _collections (collection_name, doc_id, data) VALUES ('pricing', 'growth', '{"id":"growth","name":"Growth Partner","price":"4,500","period":"month","description":"Comprehensive creative video partnership for high-growth SaaS, brands, and creators.","features":["Up to 12 high-retention short-form videos / mo","2 hero product or commercial videos","Full creative direction & hook scripting","Advanced 2D/3D motion graphics & UI animations","Priority turnaround & dedicated Slack channel","Unlimited revisions within active sprints"],"recommended":true,"popular":true,"cta":"Start Partnership","order":2}');
INSERT OR REPLACE INTO _collections (collection_name, doc_id, data) VALUES ('pricing', 'scale', '{"id":"scale","name":"Scale Engine","price":"7,500","period":"month","description":"High-volume multi-channel video production and ongoing creative campaigns.","features":["Up to 24 multi-platform video assets / mo","Full product launch & campaign video suite","Dedicated Creative Director & Senior Editor","High-end 3D CGI visuals & cinematic grading","24-hour priority response & sprint management","Multi-format repurposing across all channels"],"recommended":false,"popular":false,"cta":"Scale With Us","order":3}');
INSERT OR REPLACE INTO _collections (collection_name, doc_id, data) VALUES ('pricing', 'enterprise', '{"id":"enterprise","name":"Enterprise Custom","price":"Custom","period":"custom scope","description":"Bespoke production teams, studio film shoots, and white-glove agency integration.","features":["On-site film crew & studio production support","Full IP ownership & source project files","Custom 3D CGI & VFX pipelines","Enterprise SLA & dedicated round-the-clock team","Dedicated Slack Connect & custom billing terms"],"recommended":false,"popular":false,"cta":"Request Enterprise Quote","order":4}');